function readCustomerVehicles(customerName:string){
 let records:any[]=[];
 try{records=JSON.parse(localStorage.getItem('aa-garage-customer-records-v1')||'[]')}catch{}
 const customer=records.find(record=>String(record.name||'').trim().toLowerCase()===customerName.trim().toLowerCase());
 const customerId=sessionStorage.getItem('aa-current-garage-customer-id')||customer?.id;
 if(!customerId&&!customer)return[] as string[];
 let saved:any[]=[];
 try{saved=JSON.parse(localStorage.getItem(`aa-garage-vehicles-${customerId}`)||'[]')}catch{}
 return Array.from(new Map([...(customer?.vehicles||[]),...saved].filter((vehicle:any)=>vehicle.reg).map((vehicle:any)=>{const reg=String(vehicle.reg).trim().toUpperCase(),description=vehicle.vehicle||[vehicle.make,vehicle.model].filter(Boolean).join(' ');return[reg,`${reg} · ${description||'Vehicle'}`]})).values()) as string[];
}

const estimateWording=(value:string)=>value
 .replace(/Quotes/g,'Estimates')
 .replace(/Quote/g,'Estimate')
 .replace(/quotes/g,'estimates')
 .replace(/quote/g,'estimate');

function applyEstimateWording(root:HTMLElement){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 let node:Node|null;
 while((node=walker.nextNode())){
  const current=node.nodeValue||'',next=estimateWording(current);
  if(next!==current)node.nodeValue=next;
 }
 root.querySelectorAll<HTMLElement>('[aria-label],[placeholder],[title]').forEach(element=>{
  ['aria-label','placeholder','title'].forEach(attribute=>{
   const current=element.getAttribute(attribute);
   if(current){const next=estimateWording(current);if(next!==current)element.setAttribute(attribute,next)}
  });
 });
}

